BEGIN READ ONLY;
SELECT json_build_object('checked_at',now(),'read_only',current_setting('transaction_read_only'),'onboarding_exists',to_regclass('public.onboarding_progress') IS NOT NULL);
SELECT json_agg(x ORDER BY migration_name) FROM (SELECT migration_name,checksum,started_at,finished_at,rolled_back_at,applied_steps_count FROM public._prisma_migrations WHERE migration_name IN ('20260930000035_business_agent_identity','20260930000036_seller_agent_scope_expand','20260930000039_seller_profile_agent_key')) x;
SELECT json_build_object('agents',(SELECT count(*) FROM public.seller_agents),'profiles',(SELECT count(*) FROM public.seller_profiles),'null_profile_agent',(SELECT count(*) FROM public.seller_profiles WHERE agent_id IS NULL),'invalid_profile_chain',(SELECT count(*) FROM public.seller_profiles sp LEFT JOIN public.seller_agents a ON a.id=sp.agent_id WHERE a.id IS NULL OR a.organization_id<>sp.organization_id),'invalid_agent_chain',(SELECT count(*) FROM public.seller_agents a WHERE a.location_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.locations l JOIN public.businesses b ON b.id=l.business_id WHERE l.id=a.location_id AND b.organization_id=a.organization_id)),'invalid_lifecycle',(SELECT count(*) FROM public.seller_agents WHERE lifecycle NOT IN ('draft','active','paused','archived') OR (lifecycle IN ('active','paused') AND location_id IS NULL)),'duplicate_sellers',(SELECT count(*) FROM (SELECT location_id FROM public.seller_agents WHERE location_id IS NOT NULL AND scenario='sales' AND lifecycle<>'archived' GROUP BY location_id HAVING count(*)>1) d));
SELECT json_agg(x ORDER BY check_name) FROM public.seller_scope_precheck() x;
COMMIT;
